53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
109	        owner.setTelephone(normalizedTelephone);
110	        owner.setEmail(normalizeEmail(owner.getEmail()));
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        if (isTelephoneInUse(normalizedTelephone, null)) {
115	            throw new ResponseStatusException(HttpStatus.CONFLICT,
116	                "telephone is already in use by another owner");
117	        }
118	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
119	        this.clinicService.saveOwner(owner);
120	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
121	        headers.setLocation(UriComponentsBuilder.newInstance()
122	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
123	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
129	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
130	        if (currentOwner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        currentOwner.setAddress(ownerFieldsDto.getAddress());
134	        currentOwner.setCity(ownerFieldsDto.getCity());
135	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
136	        currentOwner.setLastName(ownerFieldsDto.getLastName());
137	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
138	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
139	        this.clinicService.saveOwner(currentOwner);
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Transactional
145	    @Override
146	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        this.clinicService.deleteOwner(owner);
152	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        HttpHeaders headers = new HttpHeaders();
163	        Pet pet = petMapper.toPet(petFieldsDto);
164	        owner.setId(ownerId);
165	        pet.setOwner(owner);
166	        pet.getType().setName(null);
167	        this.clinicService.savePet(pet);
168	        PetDto petDto = petMapper.toPetDto(pet);
